[3661] = "{item} {{!está|não está}} ao alcance{carrying}",
-- 216e438b English: the cooldown on {item} {comparison} {duration}{carrying}
[3662] = "o tempo de recarga de {item} {comparison} {duration}{carrying}",
-- 623bd8c4 English: {unit} {{!is|is not}} in a group
[3663] = "{unit} {{!está|não está}} em um grupo",
-- fedfc418 English: {unit} {{!is friendly to you|is not friendly to you}}
[3664] = "{unit} {{!é amigável com você|não é amigável com você}}",
-- 6e21eee4 English: Matches when the selected unit is dead or a ghost. A missing or unreadable unit
--     is unavailable, including under NOT. In a Via Macro announcement, choose Announcement target
--     to follow the supplied unit.
[3665] = "Corresponde quando a unidade selecionada está morta ou é um fantasma. Uma unidade ausente ou ilegível fica indisponível, inclusive sob NÃO. Em um anúncio Via macro, escolha Alvo do anúncio para seguir a unidade fornecida.",
-- eaa8232a English: Matches when the game reports the selected unit as friendly to you. This does
--     not imply party or raid membership. A missing or unreadable unit is unavailable.
[3666] = "Corresponde quando o jogo informa que a unidade selecionada é amigável com você. Isso não implica participação no grupo ou na raide. Uma unidade ausente ou ilegível fica indisponível.",
-- b9151b16 English: Assisted Combat {{!is|is not}} suggesting a spell
[3667] = "o Assistente de Combate {{!está|não está}} sugerindo um feitiço",
-- 43bf497e English: Assisted Combat {{!suggests|does not suggest}} %s
-- %s #1: %s #1: a clickable spell link, e.g. "[Fireball]"
[3668] = "o Assistente de Combate {{!sugere|não sugere}} %s",
-- 6c9594a9 English: Matches when Blizzard's Assisted Combat suggests this spell as the next cast.
--     An override counts as its base spell, and the base spell as its override. With no spell
--     chosen, matches whenever Assisted Combat suggests anything.
[3669] = "Corresponde quando o Assistente de Combate da Blizzard sugere este feitiço como o próximo a lançar. Uma substituição conta como seu feitiço base, e o feitiço base como sua substituição. Sem feitiço escolhido, corresponde sempre que o Assistente de Combate sugere qualquer coisa.",
-- 44e850ce English: Assisted Combat exists on Retail (and is declared on Forever). Where the game
--     does not offer it, for this character or specialization, or the suggestion cannot be read,
--     this condition is unavailable rather than false, including under NOT.
[3670] = "O Assistente de Combate existe no Retail (e está declarado no Forever). Onde o jogo não o oferece, para este personagem ou especialização, ou quando a sugestão não pode ser lida, esta condição fica indisponível em vez de falsa, inclusive sob NÃO.",
-- 32c737f7 English: %s {{!is|is not}} in Blizzard's Assisted Combat rotation
-- %s #1: %s #1: a clickable spell link, e.g. "[Fireball]"
[3671] = "%s {{!está|não está}} na rotação do Assistente de Combate da Blizzard",
-- ae726224 English: Matches when this spell is one Blizzard's Assisted Combat can suggest for your
--     current specialization. Its current override and its base spell count too. Use it to
--     highlight what Assisted Combat leaves out, for example a cooldown that is not in the set.
[3672] = "Corresponde quando este feitiço é um dos que o Assistente de Combate da Blizzard pode sugerir para a sua especialização atual. A substituição atual dele e o feitiço base também contam. Use para destacar o que o Assistente de Combate deixa de fora, por exemplo um tempo de recarga que não está no conjunto.",
-- 2a9b9d24 English: The set is read again whenever your spells change, never guessed. Where the
--     game does not offer Assisted Combat for this character or specialization, or the set cannot
--     be read, this condition is unavailable rather than false, including under NOT.
[3673] = "O conjunto é lido de novo sempre que os seus feitiços mudam, nunca adivinhado. Onde o jogo não oferece o Assistente de Combate para este personagem ou esta especialização, ou o conjunto não pode ser lido, esta condição fica indisponível em vez de falsa, inclusive sob NÃO.",
-- 10ac60e3 English: Assisted Combat {{!is|is not}} available
[3674] = "O Assistente de Combate {{!está|não está}} disponível",
-- d882c8a9 English: Matches when the game offers Blizzard's Assisted Combat for your character and
--     current specialization. When it does not (for example a specialization Blizzard has no
--     Assisted Combat rotation for, or a client that declares the API but does not offer the
--     feature), this is false, so a branch can fall back to your own steps.
[3675] = "Corresponde quando o jogo oferece o Assistente de Combate da Blizzard para o seu personagem e a sua especialização atual. Quando não oferece (por exemplo, uma especialização para a qual a Blizzard não tem rotação do Assistente de Combate, ou um cliente que declara a API mas não oferece o recurso), é falsa, de modo que um ramo pode recorrer aos seus próprios passos.",
-- 65331c0d English: Unavailable only where the client has no Assisted Combat API or its answer
--     cannot be read, including under NOT.
[3676] = "Indisponível apenas onde o cliente não tem a API do Assistente de Combate ou a resposta dele não pode ser lida, inclusive sob NÃO.",
